 141	static int move_all_pools(pool** src, _Atomic(pool*)* dst,
 142	                          caml_domain_state* new_owner) {
 143	  int count = 0;
 144	  while (*src) {
 145	    pool* p = *src;
 146	    *src = p->next;
 147	    p->owner = new_owner;
 148	    p->next = *dst;
 149	    *dst = p;
 150	    count++;
 151	  }
 152	  return count;
 153	}
