358	  intnat field = Long_val(vfield);
359	  if (caml_domain_alone()) {
360	    /* non-atomic CAS since only this thread can access the object */
361	    volatile value* p = &Field(obj, field);
362	    if (*p == oldval) {
363	      *p = newval;
364	      write_barrier(obj, field, oldval, newval);
365	      return Val_true;
366	    } else {
367	      return Val_false;
368	    }
369	  } else {
370	    /* need a real CAS */
371	    atomic_value* p = &Op_atomic_val(obj)[field];
372	    int cas_ret = atomic_compare_exchange_strong(p, &oldval, newval);
373	    atomic_thread_fence(memory_order_release); /* generates `dmb ish` on Arm64*/
374	    if (cas_ret) {
375	      write_barrier(obj, field, oldval, newval);
376	      return Val_true;
377	    } else {
378	      return Val_false;
379	    }
380	  }
381	}
382	CAMLprim value caml_atomic_cas (value ref, value oldval, value newval)
383	{
384	  return caml_atomic_cas_field(ref, Val_long(0), oldval, newval);
385	}
