387	CAMLprim value caml_atomic_fetch_add_field (value obj, value vfield, value incr)
388	{
389	  intnat field = Long_val(vfield);
390	  value ret;
391	  if (caml_domain_alone()) {
392	    value* p = &Op_val(obj)[field];
393	    ret = *p;
394	    CAMLassert(Is_long(ret));
395	    *p = Val_long(Long_val(ret) + Long_val(incr));
396	    /* no write barrier needed, integer write */
397	  } else {
398	    atomic_value *p = &Op_atomic_val(obj)[field];
399	    ret = atomic_fetch_add(p, 2 * Long_val(incr));
400	    atomic_thread_fence(memory_order_release); /* generates `dmb ish` on Arm64*/
401	  }
402	  return ret;
403	}
