469	/* Global memory pool.
470	
471	   The pool is structured as a ring of blocks, where each block's header
472	   contains two links: to the previous and to the next block. The data
473	   structure allows for insertions and removals of blocks in constant time,
474	   given that a pointer to the operated block is provided.
475	
476	   Initially, the pool contains a single block -- a pivot with no data, the
477	   guaranteed existence of which makes for a more concise implementation.
478	
479	   The API functions that operate on the pool receive not pointers to the
480	   block's header, but rather pointers to the block's "data" field. This
481	   behaviour is required to maintain compatibility with the interfaces of
482	   [malloc], [realloc], and [free] family of functions, as well as to hide
483	   the implementation from the user.
484	*/
485	
486	#if !defined(HAVE_MAX_ALIGN_T) && defined(_MSC_VER)
487	typedef double max_align_t;
488	#endif
489	
490	#define MAX(a, b) ((a) > (b) ? (a) : (b))
491	
492	#if defined(_M_AMD64) || defined(__x86_64__)
493	#define pool_block_align MAX(alignof(max_align_t), 16 /* for SSE */)
494	#else
495	#define pool_block_align alignof(max_align_t)
496	#endif
497	
498	struct pool_block {
499	  struct pool_block *next;
500	  struct pool_block *prev;
501	  alignas(pool_block_align) char data[]; /* flexible array member */
502	};
503	
504	static struct pool_block *pool = NULL;
505	static caml_plat_mutex pool_mutex = CAML_PLAT_MUTEX_INITIALIZER;
506	
507	/* Returns a pointer to the block header, given a pointer to "data" */
508	static struct pool_block* get_pool_block(caml_stat_block b)
509	{
510	  if (b == NULL) {
511	    return NULL;
512	  } else {
513	    return (struct pool_block *)
514	      (((char *) b) - offsetof(struct pool_block, data));
515	  }
516	}
517	
518	/* Linking a pool block into the ring */
519	static void link_pool_block(struct pool_block *pb)
520	{
521	  caml_plat_lock_blocking(&pool_mutex);
522	  pb->next = pool->next;
523	  pb->prev = pool;
524	  pool->next->prev = pb;
525	  pool->next = pb;
526	  caml_plat_unlock(&pool_mutex);
527	}
528	
529	/* Unlinking a pool block from the ring */
530	static void unlink_pool_block(struct pool_block *pb)
531	{
532	    caml_plat_lock_blocking(&pool_mutex);
533	    pb->prev->next = pb->next;
534	    pb->next->prev = pb->prev;
535	    caml_plat_unlock(&pool_mutex);
536	}
537	
538	CAMLexport void caml_stat_create_pool(void)
539	{
540	  if (pool == NULL) {
541	    pool = malloc(sizeof(struct pool_block));
542	    if (pool == NULL)
543	      caml_fatal_error("Fatal error: out of memory.\n");
544	    pool->next = pool;
545	    pool->prev = pool;
546	  }
547	}
548	
549	CAMLexport void caml_stat_destroy_pool(void)
550	{
551	  caml_plat_lock_blocking(&pool_mutex);
552	  if (pool != NULL) {
553	    pool->prev->next = NULL;
554	    while (pool != NULL) {
555	      struct pool_block *next = pool->next;
556	#ifdef _WIN32
557	      _aligned_free(pool);
558	#else
559	      free(pool);
560	#endif
561	      pool = next;
562	    }
563	    pool = NULL;
564	  }
565	  caml_plat_unlock(&pool_mutex);
566	}
567	
568	/* [sz] is a number of bytes */
569	CAMLexport caml_stat_block caml_stat_alloc_noexc(asize_t sz)
570	{
571	  /* Backward compatibility mode */
572	  if (pool == NULL)
573	    return malloc(sz);
574	  else {
575	    struct pool_block *pb;
576	#ifdef _WIN32
577	    pb = _aligned_malloc(sizeof(struct pool_block) + sz, pool_block_align);
578	#else
579	    pb = malloc(sizeof(struct pool_block) + sz);
580	#endif
581	    if (pb == NULL) return NULL;
582	    link_pool_block(pb);
583	    return &(pb->data);
584	  }
585	}
586	
587	/* [sz] and [modulo] are numbers of bytes */
588	CAMLexport void* caml_stat_alloc_aligned_noexc(asize_t sz, int modulo,
589	                                               caml_stat_block *b)
590	{
591	  char *raw_mem;
592	  uintnat aligned_mem;
593	  CAMLassert(0 <= modulo);
594	  CAMLassert(modulo < Page_size);
595	  raw_mem = (char *) caml_stat_alloc_noexc(sz + Page_size);
596	  if (raw_mem == NULL) return NULL;
597	  *b = raw_mem;
598	  raw_mem += modulo;                /* Address to be aligned */
599	  aligned_mem = (((uintnat) raw_mem / Page_size + 1) * Page_size);
600	#ifdef DEBUG
601	  {
602	    uintnat *p0 = (void *) *b;
603	    uintnat *p1 = (void *) (aligned_mem - modulo);
604	    uintnat *p2 = (void *) (aligned_mem - modulo + sz);
605	    uintnat *p3 = (void *) ((char *) *b + sz + Page_size);
606	    for (uintnat *p = p0; p < p1; p++) *p = Debug_filler_align;
607	    for (uintnat *p = p1; p < p2; p++) *p = Debug_uninit_align;
608	    for (uintnat *p = p2; p < p3; p++) *p = Debug_filler_align;
609	  }
610	#endif
611	  return (char *) (aligned_mem - modulo);
612	}
