614	/* [sz] and [modulo] are numbers of bytes */
615	CAMLexport void* caml_stat_alloc_aligned(asize_t sz, int modulo,
616	                                         caml_stat_block *b)
617	{
618	  void *result = caml_stat_alloc_aligned_noexc(sz, modulo, b);
619	  /* malloc() may return NULL if size is 0 */
620	  if ((result == NULL) && (sz != 0))
