635	CAMLexport void caml_stat_free(caml_stat_block b)
636	{
637	  /* Backward compatibility mode */
638	  if (pool == NULL)
639	    free(b);
640	  else {
641	    struct pool_block *pb = get_pool_block(b);
642	    if (pb == NULL) return;
643	    unlink_pool_block(pb);
644	#ifdef _WIN32
645	    _aligned_free(pb);
646	#else
647	    free(pb);
648	#endif
649	  }
650	}
