652	/* [sz] is a number of bytes */
653	CAMLexport caml_stat_block caml_stat_resize_noexc(caml_stat_block b, asize_t sz)
654	{
655	  if(b == NULL)
656	    return caml_stat_alloc_noexc(sz);
657	  /* Backward compatibility mode */
658	  if (pool == NULL)
659	    return realloc(b, sz);
660	  else {
661	    struct pool_block *pb = get_pool_block(b);
662	    struct pool_block *pb_new;
663	    /* Unlinking the block because it can be freed by realloc
664	       while other domains access the pool concurrently. */
665	    unlink_pool_block(pb);
666	    /* Reallocating */
667	#ifdef _WIN32
668	    pb_new = _aligned_realloc(pb, sizeof(struct pool_block) + sz,
669	                              pool_block_align);
670	#else
671	    pb_new = realloc(pb, sizeof(struct pool_block) + sz);
672	#endif
673	    if (pb_new == NULL) {
674	      /* The old block is still there, relinking it */
675	      link_pool_block(pb);
676	      return NULL;
677	    } else {
678	      link_pool_block(pb_new);
679	      return &(pb_new->data);
680	    }
681	  }
682	}
